(() => {
  const ids = ['#top-picks', '#factory', '#cases', '#catalogue', '#journal'];
  const out = {};
  ids.forEach(s => { const el = document.querySelector(s); out[s] = el ? Math.round(el.offsetHeight) : null; });
  out.doc = document.body.scrollHeight;
  const f = document.querySelector('.factory__photos');
  const st = document.querySelector('.factory__steps');
  out.photos = f ? Math.round(f.offsetHeight) : null;
  out.steps = st ? Math.round(st.offsetHeight) : null;
  const fm = document.querySelector('.feature__media img');
  out.featureImg = fm ? Math.round(fm.offsetHeight) : null;
  return out;
})()
